--
-- 表的结构 `contain`
--

CREATE TABLE `contain` (
  `pr_ID` varchar(20) NOT NULL,
  `m_ID` varchar(20) NOT NULL,
  `quantity` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- 转存表中的数据 `contain`
--


--
-- 触发器 `contain`
--
DELIMITER $$
CREATE TRIGGER `trg_check_stock` BEFORE INSERT ON `contain` FOR EACH ROW BEGIN
    DECLARE target_pharmacy_id VARCHAR(10);
    DECLARE current_stock INT DEFAULT 0;

    SELECT ph.p_ID
    INTO target_pharmacy_id
    FROM prescription pr
    JOIN pharmacist ph ON ph.ph_ID = pr.ph_ID
    WHERE pr.pr_ID = NEW.pr_ID
    LIMIT 1;

    IF target_pharmacy_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Cannot prescribe: prescription or pharmacist pharmacy not found';
    END IF;

    SELECT COALESCE(SUM(s.inventory), 0)
    INTO current_stock
    FROM store s
    WHERE s.p_ID = target_pharmacy_id
      AND s.m_ID = NEW.m_ID;

    IF current_stock < NEW.quantity THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Cannot prescribe: insufficient stock in assigned pharmacy';
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_reduce_inventory` AFTER INSERT ON `contain` FOR EACH ROW BEGIN
    DECLARE target_pharmacy_id VARCHAR(10);

    SELECT ph.p_ID
    INTO target_pharmacy_id
    FROM prescription pr
    JOIN pharmacist ph ON ph.ph_ID = pr.ph_ID
    WHERE pr.pr_ID = NEW.pr_ID
    LIMIT 1;

    UPDATE store
    SET inventory = inventory - NEW.quantity
    WHERE p_ID = target_pharmacy_id
      AND m_ID = NEW.m_ID
      AND inventory >= NEW.quantity
    ORDER BY inventory DESC
    LIMIT 1;

    IF ROW_COUNT() = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Cannot reduce inventory: no single stock row has enough quantity';
    END IF;
END
$$
DELIMITER ;

